const $=s=>document.querySelector(s);let language='en-US',spoken=true,voiceActive=false,recognition=null,speaking=false,stream=null,cameraPending=false,voiceError=false;let reminderData=[];try{reminderData=JSON.parse(localStorage.getItem('jayra-one-reminders')||'[]');if(!Array.isArray(reminderData))reminderData=[];reminderData=reminderData.filter(r=>typeof r.title==='string'&&Number.isFinite(r.time))}catch{}const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
function toast(text){$('#toasttext').textContent=text;$('#toast').hidden=false}$('#dismiss').onclick=()=>$('#toast').hidden=true;
function syncStatus(){$('#sessionstatus').textContent='Voice '+(voiceActive?'on':'off')+' · Camera '+(stream?'on':'off');$('#status').textContent=speaking?'Speaking':voiceActive?'Listening':'Ready to connect';document.body.classList.toggle('listening',voiceActive&&!speaking);document.body.classList.toggle('speaking',speaking)}
function addChat(who,text){const box=document.createElement('div');box.className='msg '+(who==='You'?'user':'');const l=document.createElement('div');l.className='chatlabel';l.textContent=who.toUpperCase();const b=document.createElement('div');b.className='bubble';b.textContent=text;box.append(l,b);$('#chat').append(box);$('#chat').scrollTop=$('#chat').scrollHeight;while($('#chat').children.length>60)$('#chat').firstElementChild.remove()}
