function stopSpeech(){window.speechSynthesis?.cancel();speaking=false;syncStatus()}
function say(text){if(!spoken||!window.speechSynthesis)return;stopSpeech();speaking=true;recognition?.abort();syncStatus();const u=new SpeechSynthesisUtterance(text);u.lang=/[\u0980-\u09ff]/.test(text)?'bn-BD':language;u.rate=.96;const finish=()=>{speaking=false;syncStatus();if(voiceActive)startRecognition()};u.onend=finish;u.onerror=finish;window.speechSynthesis.speak(u)}
