function openReminder(title=''){$('#reminderform').hidden=false;$('#add').setAttribute('aria-expanded','true');$('#rtitle').value=title;$('#rdate').min=localDate(Date.now()+60000);if(!$('#rdate').value)$('#rdate').value=localDate(Date.now()+3600000);$('#rerror').textContent='';$('#rtitle').focus();$('#reminderform').scrollIntoView({behavior:reduced?'instant':'smooth',block:'nearest'})}
function localDate(ms){const d=new Date(ms);return new Date(d-d.getTimezoneOffset()*60000).toISOString().slice(0,16)}
function closeReminder(){$('#reminderform').hidden=true;$('#add').setAttribute('aria-expanded','false');$('#add').focus()}
function persist(){try{localStorage.setItem('jayra-one-reminders',JSON.stringify(reminderData))}catch{toast('Browser storage is unavailable. Reminders will last for this visit only.')}}
function renderReminders(){const root=$('#reminders');root.replaceChildren();$('#rcount').textContent='/ '+String(reminderData.filter(r=>!r.done&&!r.fired).length).padStart(2,'0');if(!reminderData.length){const p=document.createElement('p');p.className='empty';p.textContent='A little space for what matters. Add your first reminder.';root.append(p);return}for(const r of [...reminderData].sort((a,b)=>a.time-b.time)){const row=document.createElement('div');row.className='reminder'+(r.done?' done':'');const check=document.createElement('input');check.type='checkbox';check.checked=!!r.done;check.setAttribute('aria-label','Mark '+r.title+' complete');check.onchange=()=>{r.done=check.checked;persist();renderReminders()};const wrap=document.createElement('div');wrap.className='rtext';const b=document.createElement('b');b.textContent=r.title;const small=document.createElement('small');small.textContent=new Date(r.time).toLocaleString([], {month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'})+(r.fired?' · Alerted':r.time<Date.now()&&!r.done?' · Missed while closed':'');wrap.append(b,small);const del=document.createElement('button');del.className='del';del.textContent='×';del.setAttribute('aria-label','Delete reminder '+r.title);del.onclick=()=>{reminderData=reminderData.filter(x=>x.id!==r.id);persist();renderReminders()};row.append(check,wrap,del);root.append(row)}}
$('#add').onclick=()=>$('#reminderform').hidden?openReminder():closeReminder();$('#tryreminder').onclick=()=>openReminder();$('#cancelreminder').onclick=closeReminder;
$('#reminderform').onsubmit=e=>{e.preventDefault();const title=$('#rtitle').value.trim(),time=new Date($('#rdate').value).getTime();if(!title||!Number.isFinite(time)||time<=Date.now()){$('#rerror').textContent='Choose a reminder and a future date/time.';return}reminderData.push({id:crypto.randomUUID(),title,time,done:false,fired:false});persist();renderReminders();closeReminder();$('#rdate').value='';reply('Reminder saved: '+title+'. I can alert you while this page is open.');toast('Reminder saved in this browser.')};renderReminders();
setInterval(()=>{let changed=false;for(const r of reminderData){if(!r.done&&!r.fired&&r.time<=Date.now()){r.fired=true;changed=true;toast('Reminder: '+r.title);reply('Time for your reminder: '+r.title)}}if(changed){persist();renderReminders()}},1000);
function send(text){text=text.trim();if(!text)return;addChat('You',text);if(/remind|reminder|মনে কর|রিমাইন্ড/i.test(text)){const title=text.replace(/^.*?remind me (?:to|about)\s*/i,'');openReminder(title===text?'':title);reply('What should I remember, and when? Choose the date and time in the reminder card.');return}if(/open|খোলো|খুলে/i.test(text)){launch(/code|কোড/i.test(text)?'VS Code':/file|ফাইল/i.test(text)?'Files':'Chrome');return}if(/camera|see me|ক্যামেরা|আমাকে দেখ/i.test(text)){reply('You can enable the camera in Your presence. It is a local preview only; visual understanding is not connected yet.');return}if(/what can|help|কি করতে|কী করতে/i.test(text)){reply('Here we can try sample conversations, save reminders in this browser, preview the camera and explore app controls. Full AI conversation and Windows app launching are coming next.');return}if(/[\u0980-\u09ff]/.test(text)){reply('আমি এখানে আছি, Shanaj। এটি আমাদের সিঙ্গেল-পেজ ডেমো। তুমি রিমাইন্ডার যোগ করতে পারো, ক্যামেরা প্রিভিউ দেখতে পারো, আর আমার সঙ্গে নমুনা কথোপকথন করতে পারো।');return}if(/hello|hey|hi\b|talk/i.test(text)){reply("Hi Shanaj! It's good to hear from you. I'm your Jayra demo. How's your day going?");return}if(/fine|good|great|happy/i.test(text)){reply("That sounds lovely. Shall we make a little time for your JavaScript practice? You can add a reminder whenever you're ready.");return}reply("I'm here with you. These are sample replies for the demo; a connected AI model will let us have a natural, ongoing conversation.")}
$('#command').onsubmit=e=>{e.preventDefault();const v=$('#message').value;$('#message').value='';send(v)};document.querySelectorAll('[data-say]').forEach(b=>b.onclick=()=>send(b.dataset.say));document.querySelectorAll('[data-app]').forEach(b=>b.onclick=()=>{addChat('You','Open '+b.dataset.app);launch(b.dataset.app)});$('#capabilities').onclick=()=>send('What can you do?');
function settingsOpen(show){$('#settings').hidden=!show;$('#settingsbtn').setAttribute('aria-expanded',String(show));if(show)$('#language').focus()}$('#settingsbtn').onclick=()=>settingsOpen($('#settings').hidden);$('#closesettings').onclick=()=>settingsOpen(false);$('#language').onchange=e=>{language=e.target.value;$('#languagelabel').textContent=language==='bn-BD'?'বাংলা selected':'English selected';if(voiceActive){recognition?.abort()}};function setSpoken(value){spoken=value;$('#spoken').checked=value;$('#mute').setAttribute('aria-pressed',String(!value));$('#mute').setAttribute('aria-label',value?'Mute spoken replies':'Enable spoken replies');$('#mute').style.opacity=value?'1':'.5';if(!value){stopSpeech();if(voiceActive)startRecognition()}}$('#spoken').onchange=e=>setSpoken(e.target.checked);$('#mute').onclick=()=>setSpoken(!spoken);$('#clear').onclick=()=>{$('#chat').replaceChildren();addChat('Jayra','A fresh conversation. I’m here when you’re ready.');stopSpeech()};
function stopVoice(){voiceActive=false;recognition?.abort();stopSpeech();$('#talktext').textContent='Start talking';$('#headline').textContent="I'm here. What's on your mind?";$('#voicehint').textContent='Microphone off. Start again whenever you want.';syncStatus()}
function startRecognition(){if(!voiceActive||speaking)return;const SR=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SR)return;recognition=new SR();recognition.lang=language;recognition.continuous=false;recognition.interimResults=false;recognition.onstart=()=>{syncStatus();$('#voicehint').textContent='Voice session on. Choose End conversation to stop listening.'};recognition.onresult=e=>send(e.results[0][0].transcript);recognition.onend=()=>{if(voiceActive&&!speaking&&!voiceError)startRecognition()};recognition.onerror=e=>{if(e.error==='aborted')return;voiceError=true;stopVoice();$('#voicehint').textContent=e.error==='not-allowed'?'Microphone access was not granted. You can type below.':e.error==='no-speech'?'No speech detected. Choose Start talking to try again.':'Voice recognition unavailable. You can type below.'};try{recognition.start()}catch{voiceError=true;stopVoice();$('#voicehint').textContent='Could not start microphone. Please try again or type.'}}
$('#talk').onclick=()=>{if(voiceActive){stopVoice();return}if(!(window.SpeechRecognition||window.webkitSpeechRecognition)){toast('Voice recognition is unavailable in this browser. Try a compatible browser, or type below.');$('#message').focus();return}voiceError=false;voiceActive=true;$('#talktext').textContent='End conversation';$('#headline').textContent='Go ahead. I’m listening.';syncStatus();startRecognition()};
function stopCamera(){stream?.getTracks().forEach(t=>t.stop());stream=null;$('#video').srcObject=null;$('#video').hidden=true;$('#camprompt').hidden=false;$('#cameralabel').textContent='Enable camera';$('#camtag').textContent='CAMERA OFF';$('#corecamera').setAttribute('aria-label','Turn on camera');syncStatus()}
