const canvas=$('#orb'),ctx=canvas.getContext('2d');let w=1,h=1,t=0;function resize(){const rect=canvas.getBoundingClientRect();w=rect.width;h=rect.height;const d=Math.min(devicePixelRatio,2);canvas.width=w*d;canvas.height=h*d;ctx.setTransform(d,0,0,d,0,0);if(reduced)draw()}new ResizeObserver(resize).observe(canvas);function draw(){ctx.clearRect(0,0,w,h);t+=.003;const x=w/2,y=h/2,R=Math.min(h*.35,w*.29);const glow=ctx.createRadialGradient(x,y,0,x,y,R*1.7);glow.addColorStop(0,'#a7ffb10a');glow.addColorStop(.6,'#a7ffb115');glow.addColorStop(1,'#a7ffb100');ctx.fillStyle=glow;ctx.fillRect(0,0,w,h);for(const [i,scale]of[1.12,1.28,1.43].entries()){ctx.beginPath();ctx.arc(x,y,R*scale,0,Math.PI*2);ctx.strokeStyle=i===1?'#b7f3bb23':'#b7f3bb10';ctx.lineWidth=1;ctx.stroke()}for(let i=0;i<1300;i++){const rr=R*Math.sqrt((i+.5)/1300),a=i*2.399963+t*(voiceActive?2:1),xx=rr*Math.cos(a),yy=rr*Math.sin(a)*.92;let opacity=.12+.47*Math.abs(Math.sin(a*2+t))*Math.sqrt(Math.max(0,1-(rr/R)**2));if(rr<R*.58)opacity*=.25;if(character!=="core")opacity*=.18;ctx.fillStyle=`rgba(182,255,193,${opacity})`;ctx.beginPath();ctx.arc(x+xx,y+yy,i%9===0?1.35:.72,0,7);ctx.fill()}ctx.strokeStyle='#b7f3bb6a';ctx.beginPath();ctx.ellipse(x,y,R,R*.92,.13*Math.sin(t),Math.PI*1.07,Math.PI*1.68);ctx.stroke();for(let i=0;i<4;i++){const a=t*.7+i*Math.PI/2;ctx.fillStyle='#c6ffd1';ctx.beginPath();ctx.arc(x+R*1.28*Math.cos(a),y+R*1.28*Math.sin(a),i%2?1.5:2.5,0,7);ctx.fill()}if(!reduced)requestAnimationFrame(draw)}resize();if(!reduced)draw();
